mapper.insert:
INSERT INTO sellers (
    user_id
    , brewery_name
    , representative_name
    , business_number
    , license_number
    , address
    , contact_phone
    , contact_email
) VALUES (
    #{userId}
    , #{breweryName}
    , #{representativeName}
    , #{businessNumber}
    , #{licenseNumber}
    , #{address}
    , #{contactPhone}
    , #{contactEmail}
)

mapper.select:
SELECT business_number
FROM sellers
WHERE business_number = #{businessNumber}

mapper.update:
UPDATE sellers
SET status           = #{status}
  , rejection_reason = #{rejectionReason}
  , approved_at      = CASE WHEN #{status} = 'APPROVED' THEN NOW() ELSE NULL END
WHERE id = #{id}
